const $=id=>document.getElementById(id),modal=$('modal');const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const dateLabel=s=>new Date(s+'T00:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'});const byId=new Map(watches.map(w=>[w.id,w]));const legacy=new Map(watches.flatMap(w=>(w.legacyIds||[]).map(id=>[id,w.id])));let saved=[];try{saved=[...new Set(JSON.parse(localStorage.getItem('watchatlas-saved-v2')||'[]').map(id=>legacy.get(id)||id))].filter(id=>byId.has(id))}catch{}let comp=[],view='all',shown=24;const watch=id=>byId.get(id),brands=[...new Set(watches.map(w=>w.brand))];const money=n=>n===null||n===undefined?'Price on request':new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(n);const brandStats=new Map(brands.map(b=>{let ws=watches.filter(w=>w.brand===b);return[b,{count:ws.length,collections:new Set(ws.map(w=>w.collection)).size,min:Math.min(...ws.filter(w=>w.price!==null).map(w=>w.price))}]}));const searchIndex=new Map(watches.map(w=>[w.id,`${w.brand} ${w.collection} ${w.name} ${w.ref} ${w.ref.replace(/[^a-z0-9]/gi,'')}`.toLowerCase()]));const fields=['brand','collection','movement','size','style','budget'];
function photo(w,detail=false){return `<img src="${esc(w.image)}" alt="${esc(w.brand+' '+w.name+' '+w.ref)}" ${detail?'fetchpriority="high"':'loading="lazy"'} decoding="async" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><span class="imagefallback" hidden>Photo unavailable<br><a href="${esc(w.source)}" target="_blank" rel="noopener">View product photograph ↗</a></span>`}
function options(id,values,label){$(id).innerHTML=`<option value="">${label}</option>`+values.map(v=>`<option>${esc(v)}</option>`).join('')}
options('brand',brands,'All brands');options('movement',[...new Set(watches.map(w=>w.movement))].filter(x=>x!=='Not stated'),'All movements');function collections(){options('collection',[...new Set(watches.filter(w=>!$('brand').value||w.brand===$('brand').value).map(w=>w.collection))].sort(),'All collections')};collections();
$('heroArt').insertAdjacentHTML('afterbegin',photo(watches.find(w=>w.brand==='Rolex')||watches[0],true));$('heroStats').textContent=`${watches.length.toLocaleString('en-IN')} references · ${brands.length} brands · Source-linked specifications`;$('brands').innerHTML='<span class="eyebrow">EXPLORE BY BRAND</span>'+brands.map(b=>`<button data-brand="${esc(b)}">${esc(b.toUpperCase())}<small>${brandStats.get(b).count}</small></button>`).join('');$('brandDirectory').innerHTML=brands.map(b=>{let s=brandStats.get(b);return `<button class="brandtile" data-brand="${esc(b)}"><strong>${esc(b)}</strong><span>${s.count} references · ${s.collections} collections</span><small>${Number.isFinite(s.min)?'From '+money(s.min):'Price on request'} ↗</small></button>`}).join('');document.querySelectorAll('[data-brand]').forEach(el=>el.onclick=()=>chooseBrand(el.dataset.brand));function chooseBrand(b){fields.forEach(id=>$(id).value='');$('search').value='';$('brand').value=b;collections();view='all';shown=24;render();scrollCatalog()}function scrollCatalog(){$('catalog').scrollIntoView({behavior:'smooth'})}
function budgetMatch(w){let b=$('budget').value;if(!b)return true;if(w.price===null)return false;return b==='low'?w.price<10000:b==='mid'?w.price>=10000&&w.price<50000:b==='high'?w.price>=50000&&w.price<100000:b==='premium'?w.price>=100000&&w.price<500000:b==='luxury'?w.price>=500000&&w.price<1000000:b==='ultra'?w.price>=1000000&&w.price<2500000:w.price>=2500000}
function filtered(){let q=$('search').value.toLowerCase().trim().split(/\s+/).filter(Boolean);return watches.filter(w=>(view!=='saved'||saved.includes(w.id))&&(!$('brand').value||w.brand===$('brand').value)&&(!$('collection').value||w.collection===$('collection').value)&&(!$('movement').value||w.movement===$('movement').value)&&(!$('style').value||w.style===$('style').value)&&(!$('size').value||(w.size!==null&&($('size').value==='small'?w.size<39:$('size').value==='medium'?w.size>=39&&w.size<=42:w.size>42)))&&budgetMatch(w)&&q.every(term=>searchIndex.get(w.id).includes(term)))}
function updateURL(){let p=new URLSearchParams();fields.forEach(id=>{if($(id).value)p.set(id,$(id).value)});if($('search').value)p.set('q',$('search').value);if($('sort').value!=='featured')p.set('sort',$('sort').value);if(view==='saved')p.set('view','saved');history.replaceState(null,'',location.pathname+(p.size?'?'+p.toString():'')+location.hash)}
function render(){let list=filtered();if($('sort').value==='az')list.sort((a,b)=>a.name.localeCompare(b.name));if($('sort').value==='size')list.sort((a,b)=>(a.size??Infinity)-(b.size??Infinity));if($('sort').value==='priceLow')list.sort((a,b)=>(a.price??Infinity)-(b.price??Infinity));if($('sort').value==='priceHigh')list.sort((a,b)=>(b.price??-Infinity)-(a.price??-Infinity));$('catalogTitle').textContent=view==='saved'?'Your saved watches':$('brand').value?`${$('brand').value} watches`:'Explore the database';$('resultCount').textContent=`Showing ${Math.min(shown,list.length)} of ${list.length.toLocaleString('en-IN')} references · ${new Set(list.map(w=>w.collection)).size} collections`;$('saveCount').textContent=saved.length;document.querySelectorAll('[data-brand]').forEach(el=>el.classList.toggle('selected',el.dataset.brand===$('brand').value));$('grid').innerHTML=list.length?list.slice(0,shown).map(w=>`<article class="card"><div class="product"><span class="badge">${w.sourceType==='retailer'?'RETAILER SPECS':'OFFICIAL SPECS'}</span><button class="heart" aria-label="${saved.includes(w.id)?'Unsave':'Save'} ${esc(w.ref)}" onclick="toggleSave('${w.id}')">${saved.includes(w.id)?'♥':'♡'}</button>${photo(w)}</div><div class="info"><div class="brandname">${esc(w.brand)} · ${esc(w.collection)}</div><h3>${esc(w.name)}</h3><div class="reference">${esc(w.ref)}</div><div class="price">${money(w.price)}</div><div class="muted pricetype">${esc(w.priceType||'Listed price')}</div><div class="quickSpecs"><span><small>MOVEMENT</small>${esc(w.movement)}</span><span><small>${w.sourceType==='retailer'?'CASE SIZE · RETAILER':'CASE SIZE'}</small>${w.size?`${w.size} mm`:'Not stated'}</span><span><small>CRYSTAL</small>${esc(w.specs.Crystal||'Not stated')}</span><span><small>WATER RESISTANCE</small>${esc(w.specs['Water resistance']||'Not stated')}</span></div><div class="actions"><a href="#watch=${w.id}" class="link" onclick="event.preventDefault();detail('${w.id}')">${Object.keys(w.specs).length} specifications ↗</a><label><input type="checkbox" ${comp.includes(w.id)?'checked':''} onchange="toggleCompare('${w.id}')"> Compare</label></div></div></article>`).join(''):'<div class="empty">No watches match these filters.<br><br><button class="pill" onclick="resetFilters()">Clear filters</button></div>';$('loadMore').hidden=list.length<=shown;$('loadMore').textContent=`Show 24 more · ${Math.max(0,list.length-shown).toLocaleString('en-IN')} remaining`;$('comparebar').hidden=!comp.length;$('compareCount').textContent=`${comp.length} / 6 watches selected`;$('activeFilters').innerHTML=fields.filter(id=>$(id).value).map(id=>`<button class="filterchip" onclick="clearFilter('${id}')">${esc($(id).selectedOptions[0].textContent)} ×</button>`).join('');updateURL()}
function clearFilter(id){$(id).value='';if(id==='brand')collections();shown=24;render()}function resetFilters(){fields.forEach(id=>$(id).value='');$('search').value='';shown=24;collections();render()}function showAll(){view='all';resetFilters();scrollCatalog()}function notify(s){$('toast').textContent=s;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('toast').textContent='',2800)}function toggleSave(id){saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];try{localStorage.setItem('watchatlas-saved-v2',JSON.stringify(saved))}catch{}render();if(modal.open&&$('detailSave'))$('detailSave').textContent=saved.includes(id)?'Saved ♥':'Save watch ♡'}function toggleCompare(id){if(comp.includes(id))comp=comp.filter(x=>x!==id);else if(comp.length<6)comp.push(id);else notify('Compare up to 6 watches at a time.');render()}
function sourceLinks(w){let links=[...(w.sources||[])];if(!links.some(s=>s.url===w.priceSource))links.push({label:'INR price source',url:w.priceSource});return links.filter(s=>s.url?.startsWith('https://')&&!/\.(png|jpg|jpeg|webp)(\?|$)/i.test(s.url)&&!s.label.toLowerCase().includes('photograph')).map(s=>`<li><a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.label)} ↗</a></li>`).join('')}
function detail(id,fromHash=false){let w=watch(id);if(!w)return;const gallery=[...new Set([w.image,...w.images])];$('modalBody').innerHTML=`<div class="eyebrow">${esc(w.brand)} / ${esc(w.collection)}</div><div class="detail"><div><div class="detailphoto">${photo(w,true)}</div>${gallery.length>1?`<div class="thumbs">${gallery.map((src,i)=>`<button onclick="changePhoto('${id}',${i})" aria-label="Watch photo ${i+1}"><img src="${esc(src)}" alt="${esc(w.ref)} view ${i+1}" loading="lazy"></button>`).join('')}</div>`:''}</div><div><h2>${esc(w.name)}</h2><p class="reference">${esc(w.ref)}</p><div class="price">${money(w.price)}</div><p class="muted">${esc(w.priceType)} · Price checked ${esc(dateLabel(w.priceCheckedAt||w.verifiedAt))}</p><div class="detailbuttons"><button id="detailSave" class="solid" onclick="toggleSave('${id}')">${saved.includes(id)?'Saved ♥':'Save watch ♡'}</button><a class="pill" href="${esc(w.source)}" target="_blank" rel="noopener">${w.sourceType==='retailer'?'Retailer product page':'Official product page'} ↗</a></div><div class="specprovenance">${w.sourceType==='retailer'?'Retailer-published specifications. Measurements and other details below are quoted from the linked retailer, and have not all been checked against the manufacturer.':'Specifications published by the manufacturer or its official India store.'}</div><h3>Full specifications <small class="muted">${Object.keys(w.specs).length} fields</small></h3><dl><dt>Brand</dt><dd>${esc(w.brand)}</dd><dt>Collection</dt><dd>${esc(w.collection)}</dd><dt>Reference</dt><dd>${esc(w.ref)}</dd>${Object.entries(w.specs).map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}</dl><div class="sourcenote"><strong>Sources & price information</strong><ul>${sourceLinks(w)}</ul><p>Price snapshot checked ${esc(dateLabel(w.priceCheckedAt||w.verifiedAt))}. Specifications checked ${esc(dateLabel(w.specCheckedAt||w.verifiedAt))}. Official list prices and retailer quotes are labelled separately. A listing does not confirm current stock. Missing specifications are shown as “Not stated”.</p>${w.notes.map(n=>`<p>${esc(n)}</p>`).join('')}</div></div></div>`;if(!modal.open)modal.showModal();if(!fromHash)history.replaceState(null,'',location.pathname+location.search+'#watch='+id)}
function changePhoto(id,i){let w=watch(id),gallery=[...new Set([w.image,...w.images])],el=document.querySelector('.detailphoto img');el.src=gallery[i];el.hidden=false;el.nextElementSibling.hidden=true}
function closeModal(){modal.close();if(location.hash.startsWith('#watch='))history.replaceState(null,'',location.pathname+location.search)}
function showCompare(){if(comp.length<2){notify('Select 2 to 6 watches using the Compare checkboxes.');scrollCatalog();return}let ws=comp.map(watch),keys=[...new Set(ws.flatMap(w=>Object.keys(w.specs)))];$('modalBody').innerHTML=`<div class="eyebrow">SIDE BY SIDE</div><h2 style="margin-top:15px">Compare every detail</h2><p class="muted">Up to 6 watches. Scroll horizontally to see all columns.</p><div class="comparison"><table><thead><tr><th>Specification</th>${ws.map(w=>`<th><img class="comparephoto" src="${esc(w.image)}" alt="${esc(w.name)}">${esc(w.brand)}<br>${esc(w.name)}<br><small>${esc(w.ref)}</small></th>`).join('')}</tr></thead><tbody><tr><td>INR price</td>${ws.map(w=>`<td><strong>${money(w.price)}</strong><br><small>${esc(w.priceType)}</small><br><small>Checked ${esc(dateLabel(w.priceCheckedAt||w.verifiedAt))}</small></td>`).join('')}</tr><tr><td>Specification source</td>${ws.map(w=>`<td>${w.sourceType==='retailer'?'Retailer-published':'Manufacturer-published'}</td>`).join('')}</tr>${keys.map(k=>`<tr><td>${esc(k)}</td>${ws.map(w=>`<td>${esc(w.specs[k]||'Not stated')}</td>`).join('')}</tr>`).join('')}<tr><td>Product source</td>${ws.map(w=>`<td><a href="${esc(w.source)}" target="_blank" rel="noopener">${esc(w.brand)} reference ↗</a></td>`).join('')}</tr></tbody></table></div><p class="muted">Each price shows its own source-check date. Snapshot prices may change.</p>`;modal.showModal()}
function initFilters(){const p=new URLSearchParams(location.search);if(p.get('brand')&&brands.includes(p.get('brand'))){$('brand').value=p.get('brand');collections()}fields.filter(x=>x!=='brand').forEach(id=>{let v=p.get(id);if(v&&[...$(id).options].some(o=>o.value===v))$(id).value=v});$('search').value=p.get('q')||'';if(['priceLow','priceHigh','az','size'].includes(p.get('sort')))$('sort').value=p.get('sort');if(p.get('view')==='saved')view='saved'}
$('brand').onchange=()=>{collections();shown=24;render()};['collection','movement','size','style','sort','budget'].forEach(id=>$(id).onchange=()=>{shown=24;render()});$('search').oninput=()=>{shown=24;render()};$('search').onkeydown=e=>{if(e.key==='Enter')scrollCatalog()};$('loadMore').onclick=()=>{shown+=24;render()};modal.addEventListener('click',e=>{if(e.target===modal)closeModal()});modal.addEventListener('cancel',()=>{if(location.hash.startsWith('#watch='))history.replaceState(null,'',location.pathname+location.search)});window.addEventListener('hashchange',()=>{let id=new URLSearchParams(location.hash.slice(1)).get('watch');if(id)detail(id,true)});initFilters();render();let startId=new URLSearchParams(location.hash.slice(1)).get('watch');if(startId)detail(startId,true);

fetch('update-status.json',{cache:'no-cache'}).then(r=>{if(!r.ok)throw new Error();return r.json()}).then(s=>{if(s.success&&/^\d{4}-\d{2}-\d{2}$/.test(s.checkedAt))$('updateStatus').textContent=`Weekly check: ${dateLabel(s.checkedAt)} · ${s.checked.toLocaleString('en-IN')} prices verified. Other prices retain their individual check dates.`}).catch(()=>{});
